def avoid_count(n: int, alphabet: str, banned: list[str]) -> int:
    MOD = 1_000_000_007
    if n == 0:
        return 1

    k = len(alphabet)
    char_to_idx = {ch: i for i, ch in enumerate(alphabet)}

    trans: list[list[int]] = [[-1] * k]
    bad: list[bool] = [False]

    for pattern in banned:
        cur = 0
        for ch in pattern:
            c = char_to_idx[ch]
            nxt = trans[cur][c]
            if nxt == -1:
                nxt = len(trans)
                trans[cur][c] = nxt
                trans.append([-1] * k)
                bad.append(False)
            cur = nxt
        bad[cur] = True

    num_states = len(trans)
    fail = [0] * num_states
    queue: list[int] = []

    for c in range(k):
        nxt = trans[0][c]
        if nxt != -1:
            fail[nxt] = 0
            queue.append(nxt)
        else:
            trans[0][c] = 0

    head = 0
    while head < len(queue):
        u = queue[head]
        head += 1
        if bad[fail[u]]:
            bad[u] = True
        for c in range(k):
            v = trans[u][c]
            if v != -1:
                fail[v] = trans[fail[u]][c]
                queue.append(v)
            else:
                trans[u][c] = trans[fail[u]][c]

    state_map = [-1] * num_states
    m = 0
    for u in range(num_states):
        if not bad[u]:
            state_map[u] = m
            m += 1

    mat = [[0] * m for _ in range(m)]
    for u in range(num_states):
        i = state_map[u]
        if i == -1:
            continue
        for c in range(k):
            j = state_map[trans[u][c]]
            if j != -1:
                mat[i][j] += 1

    def vec_mat_mul(vec: list[int], matrix: list[list[int]]) -> list[int]:
        res = [0] * m
        for i in range(m):
            vi = vec[i]
            if vi:
                row = matrix[i]
                for j in range(m):
                    if row[j]:
                        res[j] = (res[j] + vi * row[j]) % MOD
        return res

    def mat_mul(a: list[list[int]], b: list[list[int]]) -> list[list[int]]:
        res = [[0] * m for _ in range(m)]
        for i in range(m):
            ai = a[i]
            ri = res[i]
            for t in range(m):
                ait = ai[t]
                if ait:
                    bt = b[t]
                    for j in range(m):
                        if bt[j]:
                            ri[j] += ait * bt[j]
            for j in range(m):
                ri[j] %= MOD
        return res

    dp = [0] * m
    dp[state_map[0]] = 1

    exp = n
    base = mat
    while exp > 0:
        if exp & 1:
            dp = vec_mat_mul(dp, base)
        exp >>= 1
        if exp > 0:
            base = mat_mul(base, base)

    return sum(dp) % MOD
